import React from "react";
import { Link, useLocation } from "react-router-dom";
import "./Navbar.css"

function Navbar() {
  const location = useLocation();

  return (
    <nav className="navbar">
      <div className="navbar-logo"> Breast Cancer Detection</div>

      <div className="navbar-links">
        <Link
          to="/"
          className={`navbar-link ${
            location.pathname === "/" ? "active-link" : ""
          }`}
        >
          الرئيسية
        </Link>

        <Link
          to="/samples"
          className={`navbar-link ${
            location.pathname === "/samples" ? "active-link" : ""
          }`}
        >
          إدخال العينات
        </Link>

        <Link
          to="/features"
          className={`navbar-link ${
            location.pathname === "/features" ? "active-link" : ""
          }`}
        >
          إدخال الخصائص
        </Link>

        <Link
          to="/results"
          className={`navbar-link ${
            location.pathname === "/results" ? "active-link" : ""
          }`}
        >
          النتائج
        </Link>
      </div>
    </nav>
  );
}

export default Navbar;
